#include "frontend/core_manager.h"
#include "runtime/host_services.h"
#include "runtime/log.h"

#include <cstdio>
#include <cstring>

#ifdef RS_STATIC_CORES
/* Generated by cores/CMakeLists.txt: extern entry declarations plus the
 * RS_STATIC_CORE_TABLE list. */
#include "rs_static_cores.inc"
#else
#include <pspkernel.h>
#include <pspmodulemgr.h>
#endif

namespace rs {

const char* CoreManager::coreForSystem(db::System) {
    /* Real per-system cores land in Phases 4+ (gambatte first); every
     * system currently routes to the API-validation dummy core. */
    return "dummy";
}

#ifdef RS_STATIC_CORES

bool CoreManager::loadCore(const char* name) {
    unloadCore();
    for (const auto& entry : RS_STATIC_CORE_TABLE) {
        if (std::strcmp(entry.name, name) == 0) {
            const RSCoreAPI* api = entry.getApi();
            if (!api || api->api_version != RS_CORE_API_VERSION) {
                std::snprintf(m_error, sizeof m_error,
                              "core '%s': api version mismatch", name);
                return false;
            }
            m_core = EmulatorCore(api);
            RS_LOGI("core: '%s' ready (static)", name);
            return true;
        }
    }
    std::snprintf(m_error, sizeof m_error, "core '%s' not linked in", name);
    return false;
}

void CoreManager::unloadCore() {
    if (m_core.valid()) m_core.shutdown();
    m_core = EmulatorCore();
}

#else  /* PRX loading */

bool CoreManager::loadCore(const char* name) {
    unloadCore();

    char path[128];
    std::snprintf(path, sizeof path, "ms0:/RETROSUITE/cores/%s.prx", name);

    const SceUID mod = sceKernelLoadModule(path, 0, nullptr);
    if (mod < 0) {
        std::snprintf(m_error, sizeof m_error, "load %s failed (%08x)", path,
                      unsigned(mod));
        RS_LOGE("core: %s", m_error);
        return false;
    }

    /* The module writes its API table pointer into this slot during
     * module_start (the address travels as the start argument). */
    static const RSCoreAPI* volatile s_apiSlot;
    s_apiSlot = nullptr;
    const void* slotAddr = (const void*)&s_apiSlot;

    int status = 0;
    const int ret = sceKernelStartModule(mod, sizeof slotAddr,
                                         (void*)&slotAddr, &status, nullptr);
    if (ret < 0 || !s_apiSlot) {
        std::snprintf(m_error, sizeof m_error,
                      "start %s failed (%08x, api %p)", name, unsigned(ret),
                      (const void*)s_apiSlot);
        RS_LOGE("core: %s", m_error);
        sceKernelUnloadModule(mod);
        return false;
    }

    if (s_apiSlot->api_version != RS_CORE_API_VERSION) {
        std::snprintf(m_error, sizeof m_error,
                      "core '%s': api v%u, host v%u", name,
                      unsigned(s_apiSlot->api_version),
                      unsigned(RS_CORE_API_VERSION));
        RS_LOGE("core: %s", m_error);
        sceKernelStopModule(mod, 0, nullptr, &status, nullptr);
        sceKernelUnloadModule(mod);
        return false;
    }

    m_moduleId = mod;
    m_core = EmulatorCore(s_apiSlot);
    RS_LOGI("core: '%s' ready (prx %s)", name, path);
    return true;
}

void CoreManager::unloadCore() {
    if (m_core.valid()) m_core.shutdown();
    m_core = EmulatorCore();
    if (m_moduleId >= 0) {
        int status = 0;
        sceKernelStopModule(m_moduleId, 0, nullptr, &status, nullptr);
        sceKernelUnloadModule(m_moduleId);
        m_moduleId = -1;
        RS_LOGI("core: module unloaded");
    }
}

#endif  /* RS_STATIC_CORES */

}  // namespace rs
